package dev.raf.radar;
import android.content.*;import android.graphics.*;import android.view.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import static org.junit.Assert.*;import org.json.*;
public class MapAnchorTest {
 @Test public void labelsRemainFixedAndIgnoreOldDragOffsets()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);s.prefs.edit().clear().putBoolean("autoUpdate",false).putBoolean("sounds",false).commit();AccountClient.save(s,new JSONObject().put("user",new JSONObject().put("id",999).put("name","Fixture")).put("session","a".repeat(64)));ScreenTest.grantAccess();Point p=new Point("anchor-fixture","Fixture",55,61,false);s.update(p);s.prefs.edit().putFloat("labelX:"+p.id,140).putFloat("labelY:"+p.id,-160).putBoolean("forecast",true).commit();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(a->{Bitmap icon=a.pointIcon(p);PointF anchor=new PointF(200,200),before=a.labelPosition(p,anchor,icon);assertEquals(200,before.x,.01);assertEquals(200-icon.getHeight()/2f-a.dp(10),before.y,.01);assertFalse(a.pointOverlay.hasOnClickListeners());long at=android.os.SystemClock.uptimeMillis();for(int action:new int[]{0,2,1}){MotionEvent event=MotionEvent.obtain(at,at+20,action,before.x+action*a.dp(20),before.y,0);assertFalse(a.pointOverlay.dispatchTouchEvent(event));event.recycle();}PointF after=a.labelPosition(p,anchor,icon);assertEquals(before.x,after.x,0);assertEquals(before.y,after.y,0);Point saved=a.store.points().stream().filter(x->x.id.equals(p.id)).findFirst().get();assertEquals(55,saved.lat,0);assertEquals(61,saved.lon,0);PointF moved=a.labelPosition(p,new PointF(250,240),icon);assertEquals(50,moved.x-before.x,0);assertEquals(40,moved.y-before.y,0);});ScreenTest.capture("fixed-map-labels");}finally{AccountClient.clear(s);s.remove(p.id);}}
}
